import path from 'node:path';
import { validateDispatchBody, dispatchFirstLine, DISPATCH_PATH_RE } from '/home/user/TLDR/.claudinite/shared/engine/scheduler/validate-dispatch.mjs';

const repoRoot = '/home/user/TLDR';
const bodyPath = process.argv[2]; // path to a file containing the issue body

const body = fs.readFileSync(bodyPath, 'utf8');

const checksPath = path.join(repoRoot, '.claudinite-checks.json');
const checks = JSON.parse(fs.readFileSync(checksPath, 'utf8'));
const declaredPacks = new Set(checks.packs.map((p) => (typeof p === 'string' ? p : p.id)));

// validateDispatchBody's loadTask is called synchronously, but ESM import is
// async — pre-resolve it (if the path is well-formed) so loadTask can be sync.
const firstLine = dispatchFirstLine(body);
const m = DISPATCH_PATH_RE.exec(firstLine);
let preloaded;
let preloadError;
if (m) {
  const mjsPath = firstLine.replace(/task\.md$/, 'task.mjs');
  try {
    preloaded = (await import(path.join(repoRoot, mjsPath))).default;
  } catch (e) {
    preloadError = e;
  }
}

const result = validateDispatchBody(body, {
  exists: (p) => fs.existsSync(path.join(repoRoot, p)),
  isPackDeclared: (id) => declaredPacks.has(id),
  loadTask: () => {
    if (preloadError) throw preloadError;
    return preloaded;
  },
});

console.log(JSON.stringify(result, null, 2));

